create temporary table voicemail_audio_before on commit drop as select to_jsonb(b) as bucket from storage.buckets b where id='receptionist-voicemails';
-- Private voicemail foundation. No provider connection or manager grants are inferred.
-- Ingestion and explicit mailbox grants are service-role-only.

create table public.receptionist_mailboxes (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id),
  provider text not null default 'birchills',
  provider_mailbox_id text not null,
  display_name text not null,
  extension text not null,
  owner_user_id uuid references auth.users(id),
  notification_email text,
  email_enabled boolean,
  sync_state text not null default 'awaiting_connection' check(sync_state in ('awaiting_connection','current','error')),
  last_synced_at timestamptz,
  unique(tenant_id,provider,provider_mailbox_id), unique(tenant_id,id),
  check(sync_state <> 'current' or last_synced_at is not null)
);
create table public.receptionist_mailbox_managers (
  tenant_id uuid not null,
  mailbox_id uuid not null,
  user_id uuid not null references auth.users(id),
  granted_by uuid not null references auth.users(id),
  granted_at timestamptz not null default now(),
  primary key(mailbox_id,user_id),
  foreign key(tenant_id,mailbox_id) references public.receptionist_mailboxes(tenant_id,id)
);
create table public.receptionist_voicemails (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null,
  mailbox_id uuid not null,
  provider_message_id text not null,
  -- Snapshot the owner: repurposing Alan's extension must NOT give Rob old messages.
  owner_user_id uuid references auth.users(id),
  received_at timestamptz not null,
  caller_number text, caller_name text,
  duration_seconds integer check(duration_seconds >= 0),
  transcript text,
  email_status text not null default 'unknown' check(email_status in ('unknown','pending','sent','delivered','failed')),
  email_evidence_at timestamptz,
  email_evidence_reference text,
  email_recipient text,
  recording_path text,
  recording_available boolean generated always as (recording_path is not null) stored,
  created_at timestamptz not null default now(),
  foreign key(tenant_id,mailbox_id) references public.receptionist_mailboxes(tenant_id,id),
  unique(mailbox_id,provider_message_id),
  check(email_status = 'unknown' or (email_evidence_at is not null and nullif(email_evidence_reference,'') is not null)),
  check(recording_path is null or recording_path = tenant_id::text || '/' || mailbox_id::text || '/' || id::text)
);
create index on public.receptionist_voicemails(tenant_id,mailbox_id,received_at desc,id desc);
create table public.receptionist_voicemail_access_log (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null,
  message_id uuid not null references public.receptionist_voicemails(id),
  actor_id uuid not null references auth.users(id),
  action text not null check(action = 'playback_link_requested'),
  created_at timestamptz not null default now()
);
alter table public.receptionist_mailboxes enable row level security;
alter table public.receptionist_mailbox_managers enable row level security;
alter table public.receptionist_voicemails enable row level security;
alter table public.receptionist_voicemail_access_log enable row level security;
revoke all on public.receptionist_mailboxes, public.receptionist_mailbox_managers,
  public.receptionist_voicemails, public.receptionist_voicemail_access_log from anon, authenticated;
grant select on public.receptionist_mailboxes, public.receptionist_voicemails to authenticated;
grant all on public.receptionist_mailboxes, public.receptionist_mailbox_managers,
  public.receptionist_voicemails, public.receptionist_voicemail_access_log to service_role;

-- NO blanket tenant-admin or OpenFolk-operator bypass. Each manager is explicitly granted
-- one mailbox. No users are granted access by this migration.
create function public.can_manage_voicemail(p_tenant uuid,p_mailbox uuid)
returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists (
   select 1 from public.receptionist_mailbox_managers g
   where g.tenant_id=p_tenant and g.mailbox_id=p_mailbox and g.user_id=auth.uid()
 );
$$;
revoke all on function public.can_manage_voicemail(uuid,uuid) from public,anon;
grant execute on function public.can_manage_voicemail(uuid,uuid) to authenticated;
create policy voicemail_mailbox_read on public.receptionist_mailboxes for select to authenticated using (
  public.can_manage_voicemail(tenant_id,id) or (tenant_id=public.current_tenant_id() and owner_user_id=auth.uid())
);
create policy voicemail_message_read on public.receptionist_voicemails for select to authenticated using (
  public.can_manage_voicemail(tenant_id,mailbox_id) or (tenant_id=public.current_tenant_id() and owner_user_id=auth.uid())
);
-- SECURITY INVOKER: both the rows AND counts use caller RLS.
create function public.voicemail_mailbox_summary(p_tenant uuid)
returns table(id uuid,display_name text,extension text,notification_email text,email_enabled boolean,
 sync_state text,last_synced_at timestamptz,message_count bigint)
language sql stable security invoker set search_path='' as $$
 select b.id,b.display_name,b.extension,b.notification_email,b.email_enabled,b.sync_state,b.last_synced_at,
   (select count(*) from public.receptionist_voicemails v where v.tenant_id=b.tenant_id and v.mailbox_id=b.id)
 from public.receptionist_mailboxes b where b.tenant_id=p_tenant order by b.extension,b.display_name;
$$;
revoke all on function public.voicemail_mailbox_summary(uuid) from public,anon;
grant execute on function public.voicemail_mailbox_summary(uuid) to authenticated;
-- Only the server signs short-lived playback after a user-RLS check.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values ('receptionist-voicemails','receptionist-voicemails',false,26214400,
 array['audio/mpeg','audio/wav','audio/x-wav','audio/ogg','audio/mp4'])
on conflict(id) do nothing;
do $$begin
 if exists(select 1 from storage.buckets where id='receptionist-voicemails' and public)
 then raise exception 'Voicemail bucket must be private'; end if;
end $$;
-- Restrictive policy prevents a future broad storage policy from exposing this bucket.
create policy voicemail_no_direct_storage_access on storage.objects as restrictive
for all to anon,authenticated using(bucket_id <> 'receptionist-voicemails')
with check(bucket_id <> 'receptionist-voicemails');

-- Private voicemail intake. No routes, capture activation, user grants or source rows seeded.

create table public.receptionist_voicemail_email_routes (
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id),
 mailbox_id uuid not null, email_account_id uuid not null references public.email_accounts(id),
 recipient_email text not null check(recipient_email ~ '^[^[:space:]@]+@[^[:space:]@]+$'),
 signing_domain text not null check(signing_domain ~ '^[a-z0-9.-]+$'),
 owner_user_id uuid references auth.users(id), access_mode text not null check(access_mode in ('owner','managers_only')),
 received_from timestamptz not null, received_until timestamptz,
 binding_evidence text not null check(length(btrim(binding_evidence)) between 1 and 1000),
 verified_by uuid not null references auth.users(id), verified_at timestamptz not null default clock_timestamp(),
 enabled boolean not null default false,
 unique(tenant_id,id), foreign key(tenant_id,mailbox_id) references public.receptionist_mailboxes(tenant_id,id),
 check((access_mode='owner')=(owner_user_id is not null)),
 check(received_until is null or received_until>received_from)
);
create table public.receptionist_voicemail_intakes (
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id),
 mailbox_id uuid not null, route_id uuid not null, provider_reference uuid not null,
 owner_user_id uuid references auth.users(id), candidate jsonb not null,
 content_sha256 text not null check(content_sha256 ~ '^[a-f0-9]{64}$'),
 audio_sha256 text not null check(audio_sha256 ~ '^[a-f0-9]{64}$'),
 audio_bytes integer not null check(audio_bytes between 1 and 26214400),
 state text not null default 'prepared' check(state in ('prepared','published')),
 created_at timestamptz not null default clock_timestamp(), published_at timestamptz,
 unique(tenant_id,id), unique(tenant_id,mailbox_id,provider_reference),
 foreign key(tenant_id,mailbox_id) references public.receptionist_mailboxes(tenant_id,id),
 foreign key(tenant_id,route_id) references public.receptionist_voicemail_email_routes(tenant_id,id),
 check((state='published')=(published_at is not null))
);
create table public.receptionist_voicemail_sources (
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null, intake_id uuid not null,
 route_id uuid not null, email_account_id uuid not null references public.email_accounts(id),
 provider_email_id text not null check(provider_email_id ~ '^[a-f0-9]{1,64}$'),
 received_at timestamptz not null,
 raw_sha256 text not null check(raw_sha256 ~ '^[a-f0-9]{64}$'), raw_bytes integer not null check(raw_bytes between 1 and 1048576),
 created_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,email_account_id,provider_email_id), unique(tenant_id,id),
 foreign key(tenant_id,intake_id) references public.receptionist_voicemail_intakes(tenant_id,id),
 foreign key(tenant_id,route_id) references public.receptionist_voicemail_email_routes(tenant_id,id)
);
-- These records include private communication evidence. No owner/operator browser access.
alter table public.receptionist_voicemail_email_routes enable row level security;
alter table public.receptionist_voicemail_intakes enable row level security;
alter table public.receptionist_voicemail_sources enable row level security;
revoke all on public.receptionist_voicemail_email_routes,public.receptionist_voicemail_intakes,public.receptionist_voicemail_sources from public,anon,authenticated;
grant select,insert,update on public.receptionist_voicemail_email_routes,public.receptionist_voicemail_intakes,public.receptionist_voicemail_sources to service_role;

create function public.voicemail_intake_immutable() returns trigger language plpgsql set search_path=pg_catalog as $$
begin
 if tg_op='DELETE' then raise exception 'voicemail_evidence_immutable' using errcode='22023';end if;
 if tg_table_name='receptionist_voicemail_email_routes' and (to_jsonb(new)-'enabled')=(to_jsonb(old)-'enabled') then return new;end if;
 if tg_table_name='receptionist_voicemail_intakes' then
  if old.state='prepared' and new.state='published'
   and new.published_at is not null and (to_jsonb(new)-array['state','published_at'])=(to_jsonb(old)-array['state','published_at']) then return new;end if;
 end if;
 raise exception 'voicemail_evidence_immutable' using errcode='22023';
end $$;
create trigger voicemail_routes_immutable before update or delete on public.receptionist_voicemail_email_routes for each row execute function public.voicemail_intake_immutable();
create trigger voicemail_intakes_immutable before update or delete on public.receptionist_voicemail_intakes for each row execute function public.voicemail_intake_immutable();
create trigger voicemail_sources_immutable before update or delete on public.receptionist_voicemail_sources for each row execute function public.voicemail_intake_immutable();

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('learn-voicemail-sources','learn-voicemail-sources',false,1048576,array['message/rfc822'])
on conflict(id) do nothing;
do $$begin if exists(select 1 from storage.buckets where id in ('learn-voicemail-sources','receptionist-voicemails') and public)
 then raise exception 'voicemail_bucket_not_private';end if;end $$;
create policy voicemail_source_no_direct_storage_access on storage.objects as restrictive for all to anon,authenticated
 using(bucket_id<>'learn-voicemail-sources') with check(bucket_id<>'learn-voicemail-sources');

-- Locks match the operator master/input switch transaction. Routes are explicitly
-- enabled only after provider-account, recipient and historical access verification.
create function public.voicemail_intake_route(p_tenant uuid,p_route uuid,p_received timestamptz)
returns public.receptionist_voicemail_email_routes language plpgsql security invoker set search_path=pg_catalog as $$
declare r public.receptionist_voicemail_email_routes%rowtype;begin
 if current_user<>'service_role' then raise exception 'voicemail_intake_forbidden' using errcode='42501';end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'voicemail_snapshot_invalid' using errcode='22023';end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('learn-input-setup:'||p_tenant::text,0));
 select * into r from public.receptionist_voicemail_email_routes where id=p_route and tenant_id=p_tenant for share;
 if not found or not r.enabled or p_received is null or p_received<r.received_from or (r.received_until is not null and p_received>=r.received_until)
  then raise exception 'voicemail_route_unverified' using errcode='22023';end if;
 if not public.learn_capture_allowed(p_tenant,'email') or not public.learn_capture_allowed(p_tenant,'phone') then
  raise exception 'voicemail_capture_paused' using errcode='55000';end if;
 if not exists(select 1 from public.email_accounts a where a.id=r.email_account_id and a.tenant_id=p_tenant
  and a.provider='gmail' and a.status='active_dwd' and lower(a.email_address)=lower(r.recipient_email)) then
  raise exception 'voicemail_email_binding_changed' using errcode='22023';end if;
 return r;
end $$;

-- The trusted server has already verified the original signature, recipient,
-- parser and decoded audio. JSON contains no caller-supplied owner or storage path.
create function public.voicemail_intake_prepare(p_tenant uuid,p_route uuid,p_source jsonb,p_candidate jsonb)
returns jsonb language plpgsql security invoker set search_path=pg_catalog as $$
declare r public.receptionist_voicemail_email_routes%rowtype;i public.receptionist_voicemail_intakes%rowtype;
 s public.receptionist_voicemail_sources%rowtype;received timestamptz;reference uuid;begin
 if current_user<>'service_role' then raise exception 'voicemail_intake_forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_source) is distinct from 'object' or jsonb_typeof(p_candidate) is distinct from 'object'
  or octet_length(p_candidate::text)>100000 or octet_length(p_source::text)>4000
  or not p_source ?& array['email_id','received_at','raw_sha256','raw_bytes','content_sha256','audio_sha256','audio_bytes','signing_domain']
  or (p_source-array['email_id','received_at','raw_sha256','raw_bytes','content_sha256','audio_sha256','audio_bytes','signing_domain'])<>'{}'::jsonb
  or not p_candidate ?& array['version','system_reference','extension','caller_number','caller_name','duration_seconds','transcript']
  or (p_candidate-array['version','system_reference','extension','caller_number','caller_name','duration_seconds','transcript'])<>'{}'::jsonb
  or p_candidate->>'version' is distinct from 'birchills-voicemail-email/1'
  or p_candidate->>'extension'!~'^[0-9]{3}$'
  or p_source->>'email_id'!~'^[a-f0-9]{1,64}$'
  or coalesce(p_source->>'raw_sha256','')!~'^[a-f0-9]{64}$'
  or coalesce(p_source->>'audio_sha256','')!~'^[a-f0-9]{64}$'
  or coalesce(p_source->>'content_sha256','')!~'^[a-f0-9]{64}$'
  or coalesce(p_source->>'audio_bytes','')!~'^[0-9]+$' or coalesce(p_source->>'raw_bytes','')!~'^[0-9]+$'
  or coalesce(p_candidate->>'duration_seconds','')!~'^[0-9]+$'
  or (p_candidate->>'duration_seconds')::bigint not between 0 and 7200
  or jsonb_typeof(p_candidate->'transcript') not in ('string','null')
  or jsonb_typeof(p_candidate->'caller_number') not in ('string','null')
  or jsonb_typeof(p_candidate->'caller_name') not in ('string','null')
  or length(coalesce(p_candidate->>'caller_number',''))>30 or length(coalesce(p_candidate->>'caller_name',''))>200
  or length(coalesce(p_candidate->>'transcript',''))>50000 then
  raise exception 'voicemail_source_invalid' using errcode='22023';end if;
 received:=(p_source->>'received_at')::timestamptz; reference:=(p_candidate->>'system_reference')::uuid;
 if reference is null or not isfinite(received) then raise exception 'voicemail_source_invalid' using errcode='22023';end if;
 r:=public.voicemail_intake_route(p_tenant,p_route,received);
 if p_source->>'signing_domain' is distinct from r.signing_domain or not exists(select 1 from public.receptionist_mailboxes
  where tenant_id=p_tenant and id=r.mailbox_id and provider='birchills' and extension=p_candidate->>'extension') then
  raise exception 'voicemail_provider_binding_changed' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('voicemail-intake:'||p_tenant::text||':'||r.mailbox_id::text||':'||reference::text,0));
 select * into i from public.receptionist_voicemail_intakes where tenant_id=p_tenant and mailbox_id=r.mailbox_id and provider_reference=reference for update;
 if found then
  if i.candidate<>p_candidate or i.content_sha256<>p_source->>'content_sha256' or i.audio_sha256<>p_source->>'audio_sha256'
   or i.audio_bytes<>(p_source->>'audio_bytes')::integer or i.owner_user_id is distinct from r.owner_user_id then
   raise exception 'voicemail_duplicate_conflict' using errcode='PT409';end if;
 else
  insert into public.receptionist_voicemail_intakes(tenant_id,mailbox_id,route_id,provider_reference,owner_user_id,candidate,content_sha256,audio_sha256,audio_bytes)
  values(p_tenant,r.mailbox_id,r.id,reference,r.owner_user_id,p_candidate,p_source->>'content_sha256',p_source->>'audio_sha256',(p_source->>'audio_bytes')::integer) returning * into i;
 end if;
 insert into public.receptionist_voicemail_sources(tenant_id,intake_id,route_id,email_account_id,provider_email_id,received_at,raw_sha256,raw_bytes)
 values(p_tenant,i.id,r.id,r.email_account_id,p_source->>'email_id',received,p_source->>'raw_sha256',(p_source->>'raw_bytes')::integer)
 on conflict(tenant_id,email_account_id,provider_email_id) do nothing;
 select * into s from public.receptionist_voicemail_sources where tenant_id=p_tenant and email_account_id=r.email_account_id and provider_email_id=p_source->>'email_id';
 if s.intake_id<>i.id or s.route_id<>r.id or s.received_at<>received or s.raw_sha256<>p_source->>'raw_sha256' or s.raw_bytes<>(p_source->>'raw_bytes')::integer then
  raise exception 'voicemail_email_replay_conflict' using errcode='PT409';end if;
 return jsonb_build_object('intake_id',i.id,'source_id',s.id,'state',i.state,'audio_path',p_tenant::text||'/'||r.mailbox_id::text||'/'||i.id::text,
  'source_path',p_tenant::text||'/'||i.id::text||'/'||s.id::text||'.eml');
end $$;

-- Service must read back each uploaded object's actual bytes and verify both
-- digests before calling. Storage metadata alone does NOT establish integrity.
create function public.voicemail_intake_publish(p_tenant uuid,p_intake uuid,p_source uuid,p_raw_sha256 text,p_audio_sha256 text)
returns jsonb language plpgsql security invoker set search_path=pg_catalog as $$
declare i public.receptionist_voicemail_intakes%rowtype;s public.receptionist_voicemail_sources%rowtype;
 r public.receptionist_voicemail_email_routes%rowtype; audio_path text;source_path text;begin
 if current_user<>'service_role' then raise exception 'voicemail_intake_forbidden' using errcode='42501';end if;
 select * into i from public.receptionist_voicemail_intakes where id=p_intake and tenant_id=p_tenant for update;
 select * into s from public.receptionist_voicemail_sources where id=p_source and tenant_id=p_tenant and intake_id=p_intake;
 if i.id is null or s.id is null or p_raw_sha256 is distinct from s.raw_sha256 or p_audio_sha256 is distinct from i.audio_sha256 then
  raise exception 'voicemail_upload_unverified' using errcode='22023';end if;
 audio_path:=p_tenant::text||'/'||i.mailbox_id::text||'/'||i.id::text;
 source_path:=p_tenant::text||'/'||i.id::text||'/'||s.id::text||'.eml';
 if exists(select 1 from storage.buckets where id in ('learn-voicemail-sources','receptionist-voicemails') and public)
  or not exists(select 1 from storage.objects where bucket_id='receptionist-voicemails' and name=audio_path
   and metadata->>'size'=i.audio_bytes::text and metadata->>'mimetype'='audio/mpeg')
  or not exists(select 1 from storage.objects where bucket_id='learn-voicemail-sources' and name=source_path
   and metadata->>'size'=s.raw_bytes::text and metadata->>'mimetype'='message/rfc822') then
  raise exception 'voicemail_upload_incomplete' using errcode='55000';end if;
 if i.state='published' then
  if not exists(select 1 from public.receptionist_voicemails where id=i.id and tenant_id=p_tenant and mailbox_id=i.mailbox_id
   and owner_user_id is not distinct from i.owner_user_id and provider_message_id=i.provider_reference::text and recording_path=audio_path) then
   raise exception 'voicemail_publication_changed' using errcode='PT409';end if;
  return jsonb_build_object('state','published','message_id',i.id);
 end if;
 r:=public.voicemail_intake_route(p_tenant,s.route_id,s.received_at);
 if r.owner_user_id is distinct from i.owner_user_id or r.mailbox_id<>i.mailbox_id then raise exception 'voicemail_route_changed' using errcode='PT409';end if;
 insert into public.receptionist_voicemails(id,tenant_id,mailbox_id,provider_message_id,owner_user_id,received_at,
  caller_number,caller_name,duration_seconds,transcript,recording_path)
 values(i.id,p_tenant,i.mailbox_id,i.provider_reference::text,i.owner_user_id,s.received_at,
  i.candidate->>'caller_number',i.candidate->>'caller_name',(i.candidate->>'duration_seconds')::integer,i.candidate->>'transcript',audio_path);
 update public.receptionist_voicemail_intakes set state='published',published_at=clock_timestamp() where id=i.id;
 return jsonb_build_object('state','published','message_id',i.id);
end $$;
revoke all on function public.voicemail_intake_immutable(),public.voicemail_intake_route(uuid,uuid,timestamptz),
 public.voicemail_intake_prepare(uuid,uuid,jsonb,jsonb),public.voicemail_intake_publish(uuid,uuid,uuid,text,text) from public,anon,authenticated;
grant execute on function public.voicemail_intake_route(uuid,uuid,timestamptz),public.voicemail_intake_prepare(uuid,uuid,jsonb,jsonb),
 public.voicemail_intake_publish(uuid,uuid,uuid,text,text) to service_role;

-- Exercise existing roles only. No auth identity, mailbox, source or access row is seeded.
set local request.jwt.claim.sub='';set local request.jwt.claim.role='authenticated';set local role authenticated;
do $$begin
 begin perform public.voicemail_intake_prepare(null,null,'{}','{}');raise exception 'Client intake unexpectedly allowed';exception when insufficient_privilege then null;end;
 begin perform 1 from public.receptionist_voicemail_sources;raise exception 'Private source unexpectedly readable';exception when insufficient_privilege then null;end;
 assert (select count(*) from public.receptionist_voicemails)=0,'Unsigned client saw voicemail';
 assert not public.can_manage_voicemail('ce420000-aaaa-4000-8000-000000000099','ce420000-aaaa-4000-8000-000000000098'),'Unsigned manager accepted';
end$$;
reset role;
set local role anon;
do $$begin
 begin perform 1 from public.receptionist_voicemails;raise exception 'Anonymous voicemail unexpectedly readable';exception when insufficient_privilege then null;end;
 begin perform public.voicemail_intake_route(null,null,null);raise exception 'Anonymous intake unexpectedly allowed';exception when insufficient_privilege then null;end;
end$$;
reset role;
set local role service_role;
do $$begin
 begin perform public.voicemail_intake_route('ce420000-aaaa-4000-8000-000000000099','ce420000-aaaa-4000-8000-000000000098',now());raise exception 'Missing route admitted';exception when sqlstate '22023' then null;end;
end$$;
reset role;
do $$declare checked_table text;num bigint;begin
 foreach checked_table in array array['receptionist_mailboxes','receptionist_mailbox_managers','receptionist_voicemails','receptionist_voicemail_access_log','receptionist_voicemail_email_routes','receptionist_voicemail_intakes','receptionist_voicemail_sources'] loop
  execute format('select count(*) from public.%I',checked_table) into num;
  if num<>0 then raise exception 'New voicemail tables must remain empty';end if;
 end loop;
 if exists(select 1 from storage.buckets where id in ('receptionist-voicemails','learn-voicemail-sources') and public)
 or (select count(*) from storage.buckets where id in ('receptionist-voicemails','learn-voicemail-sources'))<>2 then raise exception 'Private buckets required';end if;
 if (select count(*) from voicemail_audio_before)>0 and (select bucket from voicemail_audio_before) is distinct from (select bucket from (select to_jsonb(b) as bucket from storage.buckets b where id='receptionist-voicemails')b) then raise exception 'Existing audio bucket changed';end if;
 if (select jsonb_agg(to_jsonb(x) order by name) from voicemail_preserved x) is distinct from (select jsonb_agg(to_jsonb(x) order by name) from (select 'public.email_messages' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.email_messages s union all select 'public.phone_calls' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.phone_calls s union all select 'public.phone_recordings' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.phone_recordings s union all select 'public.phone_transcripts' as name,count(*)::int as count,md5(coalesce(string_agg(md5((to_jsonb(s)-array['identity_summary','source_transcript_sha256' ]::text[])::text),'' order by md5((to_jsonb(s)-array['identity_summary','source_transcript_sha256' ]::text[])::text)),'')) as fingerprint from public.phone_transcripts s union all select 'public.slack_messages' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.slack_messages s union all select 'public.slack_message_versions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.slack_message_versions s union all select 'public.interactions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.interactions s union all select 'public.people' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.people s union all select 'public.companies' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.companies s union all select 'public.customer_cards' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.customer_cards s union all select 'public.sites' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.sites s union all select 'public.jobs' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.jobs s union all select 'public.provider_connections' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.provider_connections s union all select 'public.tenant_connectors' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.tenant_connectors s union all select 'public.connector_accounts' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.connector_accounts s union all select 'public.platform_jobs' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.platform_jobs s union all select 'public.feature_flags' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.feature_flags s union all select 'public.learn_business_input_pages' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_business_input_pages s union all select 'public.learn_business_input_versions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_business_input_versions s union all select 'public.learn_business_input_observations' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_business_input_observations s union all select 'public.provider_connection_events' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.provider_connection_events s union all select 'public.platform_authority_grants' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.platform_authority_grants s union all select 'public.learn_operator_input_requests' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_operator_input_requests s union all select 'public.profiles' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.profiles s union all select 'public.authority_permissions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.authority_permissions s union all select 'public.learn_business_input_request_gates' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_business_input_request_gates s union all select 'public.learn_business_input_request_permits' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_business_input_request_permits s union all select 'vault.secrets' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from vault.secrets s union all select 'public.tenants' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.tenants s union all select 'public.view_as_context' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.view_as_context s union all select 'public.config_versions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.config_versions s union all select 'public.learn_commusoft_connection_requests' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_commusoft_connection_requests s union all select 'public.learn_commusoft_verification_requests' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_commusoft_verification_requests s union all select 'public.learn_commusoft_verification_permits' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_commusoft_verification_permits s union all select 'public.learn_commusoft_verification_results' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_commusoft_verification_results s union all select 'public.learn_business_input_links' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_business_input